arguments.command:
cat > src/CheckoutPricing.Application/CalculatePayableTotal.cs <<'E'
namespace CheckoutPricing.Application;

public sealed class CalculatePayableTotal
{
    private const int ApprovedSubtotalCents = 10_000;
    private const int ApprovedPayableCents = 9_500;

    // Only the approved outcome (100.00 -> 95.00) is encoded; no general rate is approved.
    public int ForGoldCustomer(int subtotalCents)
    {
        return subtotalCents == ApprovedSubtotalCents ? ApprovedPayableCents : subtotalCents;
    }
}
